+          pnpm exec prisma db execute --config prisma7.config.ts --file scripts/e2e-project-registry.sql
+          pnpm exec prisma db execute --config prisma7.config.ts --file tests/fixtures/graph-runtime-roles.sql
+      - name: Real PostgreSQL + Next.js + Auth.js role/device/contrast/recovery QA
+        env:
+          DATABASE_URL: postgresql://graph_runtime_app:graph-runtime-ci-only@localhost:5432/blueprint_graph_runtime
+        run: pnpm exec playwright test --config playwright.graph-runtime.config.ts --grep-invert "process restart"
