+  graph-intelligence:
+    # Public standard runner; disposable databases and QA identities, never deployment.
+    if: ${{ github.event_name == 'pull_request' && startsWith(github.head_ref, 'feat/federated-graph-intelligence-') && github.event.repository.private == false }}
+    runs-on: ubuntu-24.04
+    timeout-minutes: 18
+    services:
+      postgres:
+        image: postgres:16-alpine
+        env:
+          POSTGRES_USER: blueprint
+          POSTGRES_PASSWORD: blueprint
+          POSTGRES_DB: blueprint_graph_canonical
+        ports:
+          - 5432:5432
+        options: >-
+          --health-cmd "pg_isready -U blueprint -d blueprint_graph_canonical"
+          --health-interval 5s
+          --health-timeout 5s
